usage:
import { DataTableSortable } from "@/components/design-for-ai/data-table-sortable";

// Rows render without virtualisation, so pass a page at a time (a few hundred rows at most).
<DataTableSortable
  title="Payouts"
  description="September · 4 creators"
  columns={[
    { key: "creator", header: "Creator", kind: "entity", width: 240 },
    { key: "paidOn", header: "Paid on", kind: "date", width: 120 },
    { key: "state", header: "State", kind: "status", width: 120 },
    { key: "net", header: "Net", kind: "currency", width: 140 },
  ]}
  statuses={{
    sent: { label: "Sent", tone: "positive", rank: 1 },
    held: { label: "On hold", tone: "warning", rank: 0 },
  }}
  data={payouts} // [{ id, creator, paidOn: "2026-09-30", state: "sent", net: 1840.5 }, …]
  defaultSort={{ key: "net", direction: "descending" }}
  currency="EUR"
  locale="de-DE"
  onSelectionChange={(ids) => setPicked(ids)}
  onBulkAction={(action, ids) => run(action, ids)}
/>
